custom.cssContent:
.docked-view.docked-view-left.dock-cover-shadow-left:has(.psc-docked-nav){
	border-radius: 26px !important;
	margin-top: -10px;
	margin-left: 10px;
}


.docked-view.docked-view-left.dock-cover-shadow-left:has(.psc-docked-nav) .content-wrapper {
    border-radius: 25px !important;
}

.docked-view.dock-cover-shadow-left:has(.psc-docked-nav) {
    box-shadow: 8px 12px 12px 1px rgb(0 0 0 / 20%);
}



/* tree    */


.ia_treeComponent__node:hover:not(.ia_treeComponent__node--selected){
	background-color:#b7ccd730 !important;
	transition: background-color 0.6s ease;
}

.psc-tree-nav .ia_treeComponent__alignmentGuide{
	color: transparent !important;
}


/* hover */
.psc-tree-nav .ia_treeComponent__node--selected{
	background-color:#61a5c7a3;
}

.psc-tree-nav .tree-item-label{
	 padding: 0 6px;
}


.psc-tree-nav .tree-row {

  border-radius: 15px;
}

/* no mueve si no tiene items */

/* Ocultar el espacio del expand icon vacío en nodos terminal raíz */
.psc-tree-nav .terminal-node .tree-item .terminal-expand-icon {
  display: none;
}

/* Compensar el espacio que ocupaba para que quede alineado con los padres */
.psc-tree-nav .terminal-node .tree-item .tree-item-label {
  padding-left: 5px;
}





/* ── Flecha al extremo derecho ── */
.psc-tree-nav .ia_treeComponent__expandIcon {
  order: 99;
  margin-left: auto;
  margin-right: 10px;
  opacity: 0.3;
}

/* ── Nodo padre expandido: animar sus hijos directos ── */
.psc-tree-nav .ia_treeComponent__node--expanded ~ .terminal-node .tree-item,
.psc-tree-nav .ia_treeComponent__node--expanded ~ .parent-node .tree-item {
  animation: treeFadeIn 0.4s ease forwards;
}

.psc-tree-nav .ia_treeComponent__node--expanded ~ .terminal-node,
.psc-tree-nav .ia_treeComponent__node--expanded ~ .parent-node {
  animation: treeFadeIn 0.4s ease forwards;
}

@keyframes treeFadeIn {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* Main wrapper */
.psc-menu-input {
  position:relative;
  padding:13px 15px 0px 10px!important;
  border-radius:0!important;
  border:none!important;
  border-bottom:0.5px solid var(--neutral-30)!important;
  outline:none!important;
  overflow: visible !important;
  /* Animated underline (idle + focus) */
  background:
    linear-gradient(var(--fl-line-focus),var(--fl-line-focus)) left bottom/0% 2px no-repeat,
    linear-gradient(var(--fl-line-idle),var(--fl-line-idle)) left bottom/100% 1px no-repeat;

  transition:background-size .3s ease;
}

/* Dropdown alignment fix */
.psc-menu-input.iaDropdownCommon>div>*:first-child,
.psc-header-input-mod.iaDropdownCommon>div>*:first-child { margin-left:0!important; }

/* Dropdown value padding */
.psc-menu-input.iaDropdownCommon .iaDropdownCommon_value,
.psc-menu-input-mod.iaDropdownCommon .iaDropdownCommon_value { padding:0; }

/* Focus animation */
.psc-menu-input:focus-within,
.psc-menu-input [tabindex="0"]:focus {
  outline:none!important;
  background:
    linear-gradient(var(--fl-line-focus),var(--fl-line-focus)) left bottom/100% 2px no-repeat,
    linear-gradient(var(--fl-line-idle),var(--fl-line-idle)) left bottom/100% 1px no-repeat;
}


/* Dropdown modal container */
.component-modal-large-viewport:has(.ia_dropdown__option.psc-menu-input) {
  box-shadow:none!important;
  border:none;
  background:rgba(20,20,20,0.06);
  backdrop-filter:blur(8px);
  -webkit-backdrop-filter:blur(8px);
  animation:dropdownEnter .5s ease;
  border-radius:10px!important;
}

/* Dropdown animation */
@keyframes dropdownEnter {
  from { opacity:0; transform:translateY(-15px); }
  to { opacity:1; transform:translateY(0); }
}

/* Dropdown modal styling */
.iaDropdownCommon_options_modal:has(.psc-menu-input-mod) {
  border:none!important;
  background:rgba(20,20,20,0.06) !important;
  backdrop-filter:blur(8px) !important;
  -webkit-backdrop-filter:blur(8px) !important;
  border-radius:10px!important;
  min-width:150px!important;
  box-shadow:none!important;
  animation:dropdownEnter .5s ease;
  cursor: pointer;
}
